import * as React from "react"
import "./project-block.css"

const ProjectBlock = ({ title, description, project_map }) => (
    // project_map is map of types to urls

    <div className="project-block">
        <b className="project-title">{title}</b>
        <p className="project-desc">{description}</p>
        <ul className="project-list"><span>☞</span>
            {Object.entries(project_map).map(([type, link ], idx) => {
                const indexStr = "project-" + idx;
                return (
                    <a key={indexStr} className="project-icon" href={link}>{type}</a>
                );
            }
            )}
        </ul>
    </div>
)

export default ProjectBlock